import{I as r,o as l,c as o,b6 as a,J as u,w as p,j as s,a as n}from"./chunks/framework.BUXTSoD9.js";const v=JSON.parse(`{"title":"Jobs to Be Done : trouver ce que les utilisateurs veulent vraiment accomplir","description":"Article d'introduction à Jobs to Be Done pour les lecteurs débutants. Comprendre que les utilisateurs n'achètent pas des fonctionnalités mais « emploient » votre produit pour accomplir une progression dans un contexte spécifique, et apprendre à utiliser JTBD pour décomposer la direction produit, les questions d'entretien et les prompts AI.","frontmatter":{"title":"Jobs to Be Done : trouver ce que les utilisateurs veulent vraiment accomplir","description":"Article d'introduction à Jobs to Be Done pour les lecteurs débutants. Comprendre que les utilisateurs n'achètent pas des fonctionnalités mais « emploient » votre produit pour accomplir une progression dans un contexte spécifique, et apprendre à utiliser JTBD pour décomposer la direction produit, les questions d'entretien et les prompts AI."},"headers":[],"relativePath":"fr-fr/stage-1/appendix-jobs-to-be-done/index.md","filePath":"fr-fr/stage-1/appendix-jobs-to-be-done/index.md"}`),c={name:"fr-fr/stage-1/appendix-jobs-to-be-done/index.md"},b=Object.assign(c,{setup(d){const i="Environ <strong>1,5 heure</strong>";return(m,e)=>{const t=r("ChapterIntroduction");return l(),o("div",null,[e[1]||(e[1]=a('<h1 id="jobs-to-be-done-trouver-ce-que-les-utilisateurs-veulent-vraiment-accomplir" tabindex="-1">Jobs to Be Done : trouver ce que les utilisateurs veulent vraiment accomplir <a class="header-anchor" href="#jobs-to-be-done-trouver-ce-que-les-utilisateurs-veulent-vraiment-accomplir" aria-label="Permalink to “Jobs to Be Done : trouver ce que les utilisateurs veulent vraiment accomplir”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="introduction-du-chapitre" tabindex="-1">Introduction du chapitre <a class="header-anchor" href="#introduction-du-chapitre" aria-label="Permalink to “Introduction du chapitre”">​</a></h2>',3)),u(t,{duration:i,tags:["JTBD","Besoins utilisateurs","Réflexion produit","Découverte de besoins"],coreOutput:"1 phrase JTBD qui ressemble davantage à un vrai besoin",expectedOutput:"Transformer une idée vague en un scénario utilisateur et une direction MVP plus concrets"},{default:p(()=>[...e[0]||(e[0]=[s("p",null,"Beaucoup de gens, quand ils commencent à créer un produit, font l'erreur la plus courante de concentrer toute leur attention sur « quelles fonctionnalités je vais créer ». Ils voient que d'autres ont une classification intelligente, ils veulent aussi l'ajouter ; ils voient que d'autres ont un résumé automatique, ils veulent aussi l'intégrer ; ils voient que d'autres ont fait des Agents, du multimodal, des workflows, ils se sentent obligés d'en faire autant.",-1),s("p",null,"Mais dans la réalité, les utilisateurs décident rarement d'utiliser un produit parce que « le nom de la fonctionnalité est cool ». Ils sont plutôt dans un moment précis, voulant faire avancer une tâche, et « embauchent » temporairement un outil, un service, voire une personne pour les aider à franchir cette étape.",-1),s("p",null,[n("C'est exactement ce que la méthode "),s("strong",null,"Jobs to Be Done (JTBD)"),n(" nous rappelle : "),s("strong",null,"les utilisateurs n'achètent pas des fonctionnalités en soi, ils emploient une certaine solution pour les aider à accomplir une progression.")],-1),s("p",null,"Cet article vous guidera, dans un langage aussi simple que possible, pour comprendre JTBD depuis zéro et en faire un outil d'analyse directement utilisable pour vos applications AI.",-1)])]),_:1}),e[2]||(e[2]=a(`<div class="info custom-block"><p class="custom-block-title">SOP minimale</p><p><strong>Objectif</strong> : après avoir lu, vous saurez mieux comment transformer une idée vague en un besoin avec un vrai scénario utilisateur, au lieu de n&#39;avoir en tête qu&#39;une liste de noms de fonctionnalités.</p><p><strong>Actions</strong> : écrivez 1 idée vague, trouvez 3 utilisateurs potentiels et demandez-leur « comment avez-vous géré ça la dernière fois », puis organisez le tout en 1 phrase JTBD.</p><p><strong>Résultat</strong> : vous obtiendrez une hypothèse de besoin plus claire, sachant ce que la première version doit résoudre en priorité.</p><p><strong>Navigation rapide</strong> : <a href="#jtbd-what">Qu&#39;est-ce que JTBD</a> · <a href="#jtbd-formula">La formule en une phrase</a> · <a href="#jtbd-ai">Comment l&#39;IA peut vous aider</a></p></div><h2 id="ce-que-vous-apprendrez" tabindex="-1">Ce que vous apprendrez <a class="header-anchor" href="#ce-que-vous-apprendrez" aria-label="Permalink to “Ce que vous apprendrez”">​</a></h2><ol><li>Qu&#39;est-ce que Jobs to Be Done, et pourquoi c&#39;est plus proche des besoins réels que le « brainstorming de fonctionnalités »</li><li>Comment distinguer « les fonctionnalités que les utilisateurs disent vouloir » de « ce qu&#39;ils veulent vraiment accomplir »</li><li>Comment utiliser un modèle simple pour décomposer une idée vague en contexte, déclencheur, obstacle et critère de succès</li><li>Comment utiliser JTBD pour les produits AI, les questions d&#39;entretien et l&#39;organisation des prompts</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-qu-est-ce-que-jobs-to-be-done" tabindex="-1"><a href="#top-jtbd">1. Qu&#39;est-ce que Jobs to Be Done</a> <a class="header-anchor" href="#_1-qu-est-ce-que-jobs-to-be-done" aria-label="Permalink to “1. Qu&#39;est-ce que Jobs to Be Done”">​</a></h2><p>Jobs to Be Done est souvent abrégé en <strong>JTBD</strong>. L&#39;idée centrale derrière cette méthode est liée à l&#39;expression classique popularisée par l&#39;équipe de Clayton Christensen : <strong>les utilisateurs vont « employer » un certain produit pour accomplir une tâche.</strong></p><p>La « tâche » ici n&#39;est pas une action superficielle de liste de choses à faire, mais une <strong>progression</strong> que l&#39;utilisateur souhaite voir dans son état. Par exemple :</p><ul><li>Pas « je veux un outil AI de compte rendu », mais « je veux organiser les points clés, les tâches et les responsables en moins de 10 minutes après la réunion, sans dépendre de ma mémoire pour compléter les notes »</li><li>Pas « je veux une app de comptabilité », mais « je veux savoir où va mon argent, pour ne plus être anxieux en fin de mois »</li><li>Pas « je veux un optimiseur de CV », mais « je veux soumettre un CV décent avec plus de confiance, sans douter de la qualité de ce que j&#39;ai écrit à chaque candidature »</li></ul><p>Donc, <strong>JTBD ne s&#39;intéresse pas à l&#39;apparence du produit, mais à la raison pour laquelle l&#39;utilisateur en a besoin à ce moment précis.</strong></p><p>C&#39;est aussi pourquoi de nombreux produits apparemment différents sont en réalité en concurrence pour le même job. L&#39;utilisateur qui veut « ne pas s&#39;ennuyer sur le chemin du travail » peut embaucher des vidéos courtes, des podcasts, des jeux, des chats, ou même la sieste. L&#39;utilisateur qui veut « comprendre rapidement un PDF très long » peut embaucher un outil de résumé AI, un stagiaire, un collègue, lire lui-même en serrant les dents, ou simplement ne pas lire pour l&#39;instant.</p><p>Une fois que vous regardez le problème sous cet angle, vous découvrirez que vos véritables concurrents ne sont souvent pas « une autre app qui vous ressemble », mais <strong>toutes les alternatives actuellement acceptables pour l&#39;utilisateur</strong>.</p><h2 id="_2-quelle-est-la-difference-entre-jtbd-les-personas-et-les-listes-de-fonctionnalites" tabindex="-1">2. Quelle est la différence entre JTBD, les personas et les listes de fonctionnalités <a class="header-anchor" href="#_2-quelle-est-la-difference-entre-jtbd-les-personas-et-les-listes-de-fonctionnalites" aria-label="Permalink to “2. Quelle est la différence entre JTBD, les personas et les listes de fonctionnalités”">​</a></h2><p>Beaucoup de débutants, quand ils commencent l&#39;analyse des besoins, écrivent d&#39;abord un persona : 25 ans, femme, ville de premier rang, cadre, aime les outils d&#39;efficacité, prête à essayer de nouveaux produits. Ce type d&#39;information n&#39;est pas totalement inutile, mais il est généralement <strong>insuffisant pour expliquer pourquoi une personne agirait à ce moment précis</strong>.</p><p>JTBD s&#39;intéresse davantage aux questions suivantes :</p><ul><li>Dans quel contexte a-t-il décidé de chercher une solution</li><li>Qu&#39;est-ce qui le bloquait exactement à ce moment-là</li><li>Quelle tâche veut-il faire passer à l&#39;étape suivante</li><li>Quelle méthode de fortune utilise-t-il actuellement</li><li>Si les choses sont bien résolues, quel résultat lui ferait dire « ça valait le coup »</li></ul><p>Autrement dit, <strong>le persona ressemble davantage à « qui est cette personne en gros », tandis que JTBD ressemble davantage à « que veut-elle vraiment accomplir maintenant »</strong>.</p><p>De même, les listes de fonctionnalités peuvent facilement vous égarer. Les utilisateurs disent « je veux exporter en Word », « je veux une réécriture AI », « je veux une saisie vocale » — tout cela n&#39;est qu&#39;expression de surface. JTBD continue de creuser :</p><ul><li>Pourquoi avez-vous besoin d&#39;exporter en Word maintenant, et pas en PDF ?</li><li>Vous voulez réécrire, est-ce parce que le style est mauvais, ou parce qu&#39;il faut adapter à différents publics ?</li><li>Vous voulez la saisie vocale, est-ce parce que vous êtes paresseux pour taper, ou parce que vous êtes souvent en marchant, en conduisant, ou juste après une réunion pour prendre des notes immédiatement ?</li></ul><p>Très souvent, <strong>les fonctionnalités ne sont qu&#39;une traduction temporaire du job</strong>. Si vous ne collectez que des fonctionnalités, vous risquez de construire un produit « qui empile tout ce que les utilisateurs disent » ; si vous pouvez voir le job derrière, vous avez plus de chances de créer une solution vraiment fluide et véritablement compétitive.</p><h2 id="_3-un-exemple-comprehensible-meme-par-un-debutant" tabindex="-1">3. Un exemple compréhensible même par un débutant <a class="header-anchor" href="#_3-un-exemple-comprehensible-meme-par-un-debutant" aria-label="Permalink to “3. Un exemple compréhensible même par un débutant”">​</a></h2><p>Ne vous précipitez pas pour penser à des produits AI complexes, commençons par un exemple de la vie quotidienne.</p><p>Supposons que quelqu&#39;un n&#39;a jamais le temps de prendre le petit-déjeuner avant de sortir le matin, alors il achète souvent un sandwich et un café à l&#39;entrée du métro. En surface, il « achète » un petit-déjeuner ; mais vu par JTBD, ce qu&#39;il veut vraiment accomplir pourrait être :</p><ul><li>Résoudre un repas le matin pressé, avec le moins d&#39;effort mental possible</li><li>Ne pas avoir faim avant d&#39;arriver au bureau</li><li>Ne pas retarder son trajet à cause du petit-déjeuner</li></ul><p>Ici, l&#39;utilisateur n&#39;embauche pas « un sandwich d&#39;une marque spécifique », mais une solution qui l&#39;aide à faire avancer sa matinée sans encombre. Si le convenience store d&#39;à côté est plus rapide, plus proche et plus fiable, il pourrait changer immédiatement.</p><p>Transposons cette logique aux produits AI et cela devient encore plus évident.</p><p>Par exemple, vous voulez créer un « outil AI de compte rendu de réunion ». Si vous vous arrêtez au niveau des fonctionnalités, vous commencerez facilement à penser :</p><ul><li>Faut-il supporter l&#39;upload audio</li><li>Faut-il intégrer la séparation des locuteurs</li><li>Faut-il exporter en Markdown</li><li>Faut-il générer automatiquement les tâches</li></ul><p>Tout cela n&#39;est pas faux, mais ce n&#39;est pas suffisant. Avec JTBD, on demande une couche de plus : ce que l&#39;utilisateur veut vraiment accomplir pourrait être :</p><ul><li>Je veux, dans les 10 minutes après la réunion, synchroniser les résultats de la discussion avec les absents</li><li>Je veux extraire proprement les tâches, les responsables et les délais, pour que l&#39;équipe ne collabore plus à base de mémoire</li><li>Je veux réduire le temps passé à organiser le contenu des réunions, pour consacrer mon énergie aux décisions et à l&#39;avancement</li></ul><p>Une fois le job clairement énoncé, beaucoup de priorités de fonctionnalités émergent naturellement. La chose la plus importante pour la première version n&#39;est peut-être pas « supporter 12 formats d&#39;exportation », mais :</p><ul><li>La structure du compte rendu doit être suffisamment claire</li><li>L&#39;extraction des tâches doit être fiable</li><li>Le lien de partage doit être pratique</li><li>Le résultat doit être assez fiable pour être directement transféré à l&#39;équipe</li></ul><p>C&#39;est la valeur de JTBD : <strong>il vous aide à passer de « quelles capacités dois-je empiler » à « quelle progression je dois aider l&#39;utilisateur à accomplir ».</strong></p><h2 id="_4-un-modele-jtbd-pratique" tabindex="-1">4. Un modèle JTBD pratique <a class="header-anchor" href="#_4-un-modele-jtbd-pratique" aria-label="Permalink to “4. Un modèle JTBD pratique”">​</a></h2><p>Si vous êtes débutant, ne cherchez pas à rendre JTBD trop académique. Saisissez les 5 éléments les plus utiles pour commencer.</p><h3 id="_4-1-contexte" tabindex="-1">4.1 Contexte <a class="header-anchor" href="#_4-1-contexte" aria-label="Permalink to “4.1 Contexte”">​</a></h3><p>À quel moment, dans quel environnement l&#39;utilisateur pense-t-il à ce produit ?</p><ul><li>Juste après une réunion</li><li>Quand le patron demande soudainement un document</li><li>Le soir en préparant une candidature</li><li>En fin de mois quand on réalise que l&#39;argent manque à nouveau</li></ul><p><strong>Un besoin sans contexte n&#39;est généralement pas encore assez réel.</strong></p><h3 id="_4-2-declencheur" tabindex="-1">4.2 Déclencheur <a class="header-anchor" href="#_4-2-declencheur" aria-label="Permalink to “4.2 Déclencheur”">​</a></h3><p>Qu&#39;est-ce qui le pousse à chercher immédiatement une solution ?</p><ul><li>Être submergé par un long document, sans savoir par où commencer</li><li>Devoir rendre un document demain, et découvrir aujourd&#39;hui que le format est chaotique</li><li>Venir d&#39;être rappelé par le manager sur l&#39;avancement, et réaliser qu&#39;on n&#39;a pas organisé clairement</li><li>Vouloir tenir un journal, mais l&#39;écriture manuelle, le copier-coller et l&#39;organisation sont trop pénibles</li></ul><p>Le déclencheur porte souvent une émotion. Cette émotion est importante, car elle détermine pourquoi l&#39;utilisateur passe à l&#39;action à ce moment précis.</p><h3 id="_4-3-la-progression-souhaitee" tabindex="-1">4.3 La progression souhaitée <a class="header-anchor" href="#_4-3-la-progression-souhaitee" aria-label="Permalink to “4.3 La progression souhaitée”">​</a></h3><p>Il ne veut pas seulement « faire une action », mais se propulser vers quel nouvel état ?</p><ul><li>Du chaos à la clarté</li><li>De l&#39;anxiété à la tranquillité</li><li>De la procrastination au démarrage</li><li>De l&#39;inefficacité à la fluidité</li><li>De l&#39;incapacité à expliquer à la capacité de livrer directement</li></ul><p>À cette étape, le mot « progression » est crucial. Parce que beaucoup de gens n&#39;achètent pas vraiment un outil, mais un <strong>changement d&#39;état</strong>.</p><h3 id="_4-4-l-alternative-actuelle" tabindex="-1">4.4 L&#39;alternative actuelle <a class="header-anchor" href="#_4-4-l-alternative-actuelle" aria-label="Permalink to “4.4 L&#39;alternative actuelle”">​</a></h3><p>Sans votre produit, comment fait-il ?</p><ul><li>Copier-coller manuel</li><li>Se débrouiller avec Excel ou Notes</li><li>Demander de l&#39;aide à un collègue</li><li>Remettre à plus tard</li><li>Naviguer entre plusieurs outils</li></ul><p>Qui est l&#39;alternative, qui est votre véritable environnement concurrentiel.</p><h3 id="_4-5-critere-de-succes" tabindex="-1">4.5 Critère de succès <a class="header-anchor" href="#_4-5-critere-de-succes" aria-label="Permalink to “4.5 Critère de succès”">​</a></h3><p>Quand peut-on dire que le problème est vraiment résolu ?</p><ul><li>Obtenir un résultat partageable en 10 minutes</li><li>Pouvoir envoyer aux autres sans révision majeure</li><li>Ne pas facilement oublier, se tromper ou manquer quelque chose</li><li>Savoir quoi faire dès la première utilisation</li></ul><p>Si vous ne savez même pas « comment l&#39;utilisateur juge si ça valait le coup », cette direction n&#39;est probablement pas encore assez aboutie.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-la-formule-en-une-phrase-prete-a-l-emploi" tabindex="-1"><a href="#top-jtbd">5. La formule en une phrase, prête à l&#39;emploi</a> <a class="header-anchor" href="#_5-la-formule-en-une-phrase-prete-a-l-emploi" aria-label="Permalink to “5. La formule en une phrase, prête à l&#39;emploi”">​</a></h2><p>Quand vous voulez clarifier une direction produit, vous pouvez d&#39;abord utiliser cette formule très pratique :</p><blockquote><p>Quand __________, je veux __________, afin de __________. Actuellement, je ne peux accomplir cette tâche qu&#39;en __________.</p></blockquote><p>Par exemple :</p><blockquote><p>Quand je sors d&#39;une réunion de projet chargée en informations, je veux obtenir rapidement un compte rendu structuré avec les tâches, les responsables et les délais, afin de pouvoir synchroniser immédiatement l&#39;équipe et faire avancer l&#39;exécution. Actuellement, je ne peux m&#39;en sortir qu&#39;en me remémorant, en fouillant dans l&#39;historique de chat et en organisant manuellement.</p></blockquote><p>Autre exemple :</p><blockquote><p>Quand je prépare une candidature pour un nouveau poste, je veux rapidement adapter mes expériences existantes en une version plus ciblée sur le poste, afin de soumettre un CV décent avec plus de confiance. Actuellement, je ne fais que copier-coller l&#39;ancien CV, modifier les formulations à la main, et à la fin, je suis de moins en moins sûr de moi.</p></blockquote><p>Si vous pouvez écrire une phrase avec ce niveau de clarté, la conception des pages, des prompts et la hiérératisation des fonctionnalités deviendront beaucoup plus faciles.</p><h2 id="_6-pour-les-produits-ai-trois-couches-de-job-a-examiner-particulierement" tabindex="-1">6. Pour les produits AI, trois couches de job à examiner particulièrement <a class="header-anchor" href="#_6-pour-les-produits-ai-trois-couches-de-job-a-examiner-particulierement" aria-label="Permalink to “6. Pour les produits AI, trois couches de job à examiner particulièrement”">​</a></h2><p>Beaucoup de produits AI semblent impressionnants en démonstration, mais ne parviennent pas à fidéliser les utilisateurs une fois en ligne. La raison courante est qu&#39;ils ne résolvent que l&#39;action de surface, pas le job plus profond.</p><p>Vous pouvez grossièrement diviser un job en trois couches :</p><h3 id="_6-1-couche-fonctionnelle" tabindex="-1">6.1 Couche fonctionnelle <a class="header-anchor" href="#_6-1-couche-fonctionnelle" aria-label="Permalink to “6.1 Couche fonctionnelle”">​</a></h3><p>Quelle est la tâche la plus en surface ?</p><ul><li>Résumer un document</li><li>Réécrire un texte</li><li>Extraire les tâches</li><li>Générer une image</li></ul><p>C&#39;est la couche que les utilisateurs expriment le plus facilement.</p><h3 id="_6-2-couche-emotionnelle" tabindex="-1">6.2 Couche émotionnelle <a class="header-anchor" href="#_6-2-couche-emotionnelle" aria-label="Permalink to “6.2 Couche émotionnelle”">​</a></h3><p>Quel inconfort l&#39;utilisateur veut-il réduire, ou quel ressenti veut-il obtenir ?</p><ul><li>Ne plus paniquer</li><li>Ne plus paraître non professionnel</li><li>Ne plus recommencer de zéro à chaque fois</li><li>Avoir plus de sentiment de contrôle</li></ul><p>Beaucoup de volontés de paiement sont en réalité liées à la couche émotionnelle.</p><h3 id="_6-3-couche-sociale" tabindex="-1">6.3 Couche sociale <a class="header-anchor" href="#_6-3-couche-sociale" aria-label="Permalink to “6.3 Couche sociale”">​</a></h3><p>Comment l&#39;utilisateur veut-il être perçu par les autres ?</p><ul><li>Avoir l&#39;air plus fiable</li><li>Avoir l&#39;air plus organisé dans l&#39;équipe</li><li>Avoir l&#39;air plus professionnel face aux clients</li><li>Avoir l&#39;air plus expressif sur les réseaux sociaux</li></ul><p>Si vous ne faites que la couche fonctionnelle, le produit sera facilement remplaçable ; si vous comprenez aussi les couches émotionnelle et sociale, vous trouverez plus facilement une valeur vraiment engageante.</p><h2 id="_7-utiliser-jtbd-pour-filtrer-les-directions-produit-en-sens-inverse" tabindex="-1">7. Utiliser JTBD pour filtrer les directions produit en sens inverse <a class="header-anchor" href="#_7-utiliser-jtbd-pour-filtrer-les-directions-produit-en-sens-inverse" aria-label="Permalink to “7. Utiliser JTBD pour filtrer les directions produit en sens inverse”">​</a></h2><p>Parfois, ce n&#39;est pas que vous avez déjà un produit, mais que vous avez 3 à 5 idées et ne savez pas laquelle réaliser. JTBD est alors idéal pour le filtrage.</p><p>Vous pouvez prendre chaque idée et vous poser 5 questions :</p><ol><li>Le contexte correspondant à cette idée est-il suffisamment spécifique ?</li><li>Les utilisateurs utilisent-ils déjà une méthode de fortune pour s&#39;en sortir ?</li><li>La douleur de ce job est-elle suffisamment forte, ou suffisamment fréquente ?</li><li>Si je le fais bien, l&#39;utilisateur sentira-t-il clairement que « son état s&#39;est amélioré » ?</li><li>La première version peut-elle se concentrer uniquement sur l&#39;étape clé de ce job, pour produire une version petite mais utile ?</li></ol><p>Si une direction, après réflexion, ne peut toujours être décrite que par « ça a l&#39;air intéressant », sans pouvoir préciser le déclencheur, l&#39;alternative et le critère de succès, c&#39;est probablement encore une inspiration vague, pas une direction aboutie.</p><h2 id="_8-des-questions-pretes-a-l-emploi-pour-interroger-les-utilisateurs" tabindex="-1">8. Des questions prêtes à l&#39;emploi pour interroger les utilisateurs <a class="header-anchor" href="#_8-des-questions-pretes-a-l-emploi-pour-interroger-les-utilisateurs" aria-label="Permalink to “8. Des questions prêtes à l&#39;emploi pour interroger les utilisateurs”">​</a></h2><p>Beaucoup de gens, quand ils font une étude, demandent : « Quelle fonctionnalité voulez-vous ? » Ce type de question génère facilement des réponses superficielles.</p><p>JTBD est plus adapté pour poser les questions suivantes :</p><ul><li>Quand est la dernière fois que vous avez rencontré ce problème ?</li><li>Que faisiez-vous à ce moment-là, pourquoi étiez-vous bloqué ?</li><li>Comment l&#39;avez-vous finalement résolu ?</li><li>Dans ce processus, qu&#39;est-ce qui était le plus pénible, le plus lent, le plus angoissant ?</li><li>S&#39;il y avait un outil pour vous aider, quel résultat vous ferait dire qu&#39;il est vraiment utile ?</li><li>Quelles alternatives avez-vous essayées ? Pourquoi n&#39;étaient-elles pas assez bonnes ?</li></ul><p>L&#39;avantage de cette approche est qu&#39;elle ramène la conversation vers les expériences réelles, au lieu de rester sur des préférences imaginaires.</p><h2 id="_9-utiliser-l-ia-pour-vous-aider-dans-la-decomposition-jtbd" tabindex="-1">9. Utiliser l&#39;IA pour vous aider dans la décomposition JTBD <a class="header-anchor" href="#_9-utiliser-l-ia-pour-vous-aider-dans-la-decomposition-jtbd" aria-label="Permalink to “9. Utiliser l&#39;IA pour vous aider dans la décomposition JTBD”">​</a></h2><p>JTBD n&#39;a pas été inventé par l&#39;IA, mais l&#39;IA est très bien adaptée pour vous aider à organiser et affiner les analyses JTBD.</p><p>Par exemple, si vous avez collecté 5 à 10 retours utilisateurs, vous pouvez les confier au modèle et lui demander de les synthétiser selon la structure suivante :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de jouer le rôle d&#39;assistant de recherche produit.</span></span>
<span class="line"><span>Je vais vous donner des citations d&#39;utilisateurs, ne donnez pas d&#39;abord de suggestions de fonctionnalités,</span></span>
<span class="line"><span>mais organisez-les d&#39;abord selon le framework Jobs to Be Done :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Dans quel contexte se trouve l&#39;utilisateur</span></span>
<span class="line"><span>2. Quel est l&#39;événement déclencheur de son action</span></span>
<span class="line"><span>3. Quelle progression veut-il vraiment accomplir</span></span>
<span class="line"><span>4. Quelle est l&#39;alternative actuelle</span></span>
<span class="line"><span>5. Quel critère de succès est le plus important pour lui</span></span>
<span class="line"><span>6. Quels mots émotionnels reviennent dans ces retours</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enfin, organisez tout cela en 3 hypothèses JTBD les plus dignes d&#39;être validées en priorité.</span></span></code></pre></div><p>Si vous avez déjà une idée, vous pouvez aussi demander à l&#39;IA de faire une première convergence :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un [votre idée produit].</span></span>
<span class="line"><span>Ne me donnez pas directement une liste de fonctionnalités, mais analysez avec la méthode Jobs to Be Done :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Quels contextes spécifiques ce produit pourrait-il servir</span></span>
<span class="line"><span>2. Quel est le job central que l&#39;utilisateur veut accomplir dans chaque contexte</span></span>
<span class="line"><span>3. Quelles sont les alternatives existantes</span></span>
<span class="line"><span>4. Quel job est le plus adapté comme point de départ MVP, et pourquoi</span></span>
<span class="line"><span>5. Écrivez le job final recommandé en une phrase JTBD claire</span></span></code></pre></div><p>L&#39;avantage de cette approche est que vous ne vous faites pas immédiatement emporter par l&#39;IA vers « 50 idées de fonctionnalités », mais vous clarifiez d&#39;abord la direction.</p><h2 id="_10-les-4-erreurs-les-plus-courantes-chez-les-debutants" tabindex="-1">10. Les 4 erreurs les plus courantes chez les débutants <a class="header-anchor" href="#_10-les-4-erreurs-les-plus-courantes-chez-les-debutants" aria-label="Permalink to “10. Les 4 erreurs les plus courantes chez les débutants”">​</a></h2><h3 id="_10-1-ecrire-le-job-comme-un-nom-de-fonctionnalite" tabindex="-1">10.1 Écrire le job comme un nom de fonctionnalité <a class="header-anchor" href="#_10-1-ecrire-le-job-comme-un-nom-de-fonctionnalite" aria-label="Permalink to “10.1 Écrire le job comme un nom de fonctionnalité”">​</a></h3><p>« Résumé AI », « Classification intelligente », « Génération automatique » — ce ne sont pas des jobs, ce sont seulement des modes de réalisation possibles.</p><h3 id="_10-2-ecrire-un-public-beaucoup-trop-large" tabindex="-1">10.2 Écrire un public beaucoup trop large <a class="header-anchor" href="#_10-2-ecrire-un-public-beaucoup-trop-large" aria-label="Permalink to “10.2 Écrire un public beaucoup trop large”">​</a></h3><p>« Tous les professionnels », « tous les étudiants », « tous les entrepreneurs » — tout cela est généralement trop vague. Plus c&#39;est vague, plus il est difficile de voir les scénarios réels.</p><h3 id="_10-3-ecouter-seulement-ce-que-les-utilisateurs-disent-sans-observer-ce-qu-ils-font" tabindex="-1">10.3 Écouter seulement ce que les utilisateurs disent, sans observer ce qu&#39;ils font <a class="header-anchor" href="#_10-3-ecouter-seulement-ce-que-les-utilisateurs-disent-sans-observer-ce-qu-ils-font" aria-label="Permalink to “10.3 Écouter seulement ce que les utilisateurs disent, sans observer ce qu&#39;ils font”">​</a></h3><p>Les utilisateurs peuvent décrire ce qu&#39;ils veulent, mais leurs véritables priorités sont souvent cachées dans la façon dont ils se débrouillent actuellement.</p><h3 id="_10-4-vouloir-construire-une-plateforme-complete-des-le-debut" tabindex="-1">10.4 Vouloir construire une plateforme complète dès le début <a class="header-anchor" href="#_10-4-vouloir-construire-une-plateforme-complete-des-le-debut" aria-label="Permalink to “10.4 Vouloir construire une plateforme complète dès le début”">​</a></h3><p>La bonne approche de JTBD n&#39;est généralement pas « je vais construire une grande plateforme qui fait tout », mais cibler d&#39;abord l&#39;étape la plus critique dans un scénario, et la rendre extrêmement fluide.</p><h2 id="_11-resume" tabindex="-1">11. Résumé <a class="header-anchor" href="#_11-resume" aria-label="Permalink to “11. Résumé”">​</a></h2><p>La valeur la plus importante de Jobs to Be Done n&#39;est pas de vous donner un nouveau terme, mais de vous aider à changer de perspective : <strong>ne vous fixez pas uniquement sur les fonctionnalités du produit, mais sur ce que l&#39;utilisateur veut faire avancer à l&#39;étape suivante.</strong></p><p>Quand vous commencerez à vous poser répétitivement ces questions :</p><ul><li>Dans quel contexte l&#39;utilisateur embauche-t-il ce produit</li><li>Où est-il exactement bloqué</li><li>Quelle méthode de fortune utilise-t-il actuellement</li><li>Une fois le problème résolu, quel sera le changement d&#39;état</li></ul><p>Vous découvrirez que beaucoup d&#39;idées floues deviennent soudainement claires, et que beaucoup de fonctionnalités tape-à-l&#39;œil deviennent soudainement moins importantes.</p><p>Créer un produit, surtout un produit AI, le plus grand risque est de se laisser absorber par la démonstration de capacités dès le début. JTBD vous aide à ramener l&#39;attention sur ce qui compte vraiment : <strong>pourquoi l&#39;utilisateur a besoin de vous, et quelle progression vous l&#39;aidez à accomplir.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-comment-utiliser-l-ia-pour-mettre-en-pratique-jtbd" tabindex="-1"><a href="#top-jtbd">12. Comment utiliser l&#39;IA pour mettre en pratique JTBD</a> <a class="header-anchor" href="#_12-comment-utiliser-l-ia-pour-mettre-en-pratique-jtbd" aria-label="Permalink to “12. Comment utiliser l&#39;IA pour mettre en pratique JTBD”">​</a></h2><p>JTBD n&#39;a pas été inventé par l&#39;IA, mais l&#39;IA est très bien adaptée pour servir d&#39;assistante de recherche, d&#39;assistante d&#39;organisation et de miroir dans cette méthode. L&#39;essentiel est : <strong>laissez l&#39;IA vous aider à organiser et à élargir, pas à deviner les utilisateurs à votre place.</strong></p><p>Voici comment l&#39;utiliser :</p><h3 id="_12-1-laissez-l-ia-reecrire-vos-idees-vagues-en-hypotheses-jtbd" tabindex="-1">12.1 Laissez l&#39;IA réécrire vos idées vagues en hypothèses JTBD <a class="header-anchor" href="#_12-1-laissez-l-ia-reecrire-vos-idees-vagues-en-hypotheses-jtbd" aria-label="Permalink to “12.1 Laissez l&#39;IA réécrire vos idées vagues en hypothèses JTBD”">​</a></h3><p>Quand vous n&#39;avez qu&#39;une description vague en tête, comme « je veux créer un outil pour aider les étudiants à trouver un stage », vous pouvez d&#39;abord demander à l&#39;IA de la décomposer en plusieurs jobs possibles :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>J&#39;ai une idée produit vague : [votre idée]</span></span>
<span class="line"><span>Ne me donnez pas directement une liste de fonctionnalités, mais analysez avec la méthode Jobs to Be Done :</span></span>
<span class="line"><span>1. Quels contextes spécifiques cela pourrait-il correspondre</span></span>
<span class="line"><span>2. Quelle progression l&#39;utilisateur veut vraiment accomplir dans chaque contexte</span></span>
<span class="line"><span>3. Quelles pourraient être les alternatives actuelles</span></span>
<span class="line"><span>4. Quel job est le plus adapté pour un MVP en premier</span></span>
<span class="line"><span>Écrivez chaque job en une phrase JTBD claire.</span></span></code></pre></div><p>Vous pouvez même écrire une entrée très basique :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un truc pour aider les étudiants à trouver un stage.</span></span>
<span class="line"><span>Je ne sais pas encore exactement quoi faire, aidez-moi à réfléchir à ce que les utilisateurs veulent vraiment accomplir.</span></span></code></pre></div><p>L&#39;IA pourrait répondre quelque chose comme :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Directions JTBD possibles :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Quand je prépare ma première candidature de stage, je veux savoir rapidement quels documents préparer en priorité,</span></span>
<span class="line"><span>pour ne pas reporter ma candidature à cause de la confusion.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Quand je vois une offre de stage, je veux juger rapidement si ça vaut le coup de postuler,</span></span>
<span class="line"><span>pour ne pas perdre trop de temps sur des postes inadaptés.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Quand je commence à postuler, je veux adapter mon CV existant en une version plus ciblée sur le poste,</span></span>
<span class="line"><span>pour pouvoir postuler plus vite et améliorer mon taux de réussite.</span></span></code></pre></div><p>La valeur de ce type de résultat est qu&#39;il décompose votre pensée vague en plusieurs directions plus proches de scénarios réels.</p><h3 id="_12-2-laissez-l-ia-organiser-les-citations-d-utilisateurs" tabindex="-1">12.2 Laissez l&#39;IA organiser les citations d&#39;utilisateurs <a class="header-anchor" href="#_12-2-laissez-l-ia-organiser-les-citations-d-utilisateurs" aria-label="Permalink to “12.2 Laissez l&#39;IA organiser les citations d&#39;utilisateurs”">​</a></h3><p>Si vous avez déjà fait quelques entretiens, vous pouvez confier les notes à l&#39;IA pour qu&#39;elle en extraie les contextes, déclencheurs, alternatives et critères de succès qui reviennent :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les citations de 5 utilisateurs.</span></span>
<span class="line"><span>Ne donnez pas d&#39;abord de solution, mais organisez selon le framework JTBD :</span></span>
<span class="line"><span>1. Dans quel contexte se trouve l&#39;utilisateur</span></span>
<span class="line"><span>2. Quel est l&#39;événement déclencheur de son action</span></span>
<span class="line"><span>3. Quelle progression veut-il vraiment accomplir</span></span>
<span class="line"><span>4. Quelle est l&#39;alternative actuelle</span></span>
<span class="line"><span>5. Quel critère de succès est le plus important pour lui</span></span>
<span class="line"><span>6. Quelles informations reviennent chez plusieurs utilisateurs</span></span>
<span class="line"><span>Enfin, organisez en 3 hypothèses JTBD prioritaires pour validation.</span></span></code></pre></div><p>Une entrée très simple pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>J&#39;ai demandé à 3 personnes, ils m&#39;ont dit à peu près ceci :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Chaque fois que je dois postuler, je dois refaire mon CV, c&#39;est vraiment pénible.</span></span>
<span class="line"><span>2. En fait, ce que je crains le plus, c&#39;est de ne pas savoir si ce que j&#39;écris est correct.</span></span>
<span class="line"><span>3. Actuellement, je demande aux anciens de m&#39;aider à relire, mais je n&#39;ose pas toujours les déranger.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Organisez-moi ça : que veulent-ils vraiment accomplir ?</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Résultat de l&#39;organisation :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Contexte commun : préparer une candidature de stage, besoin de traiter le CV</span></span>
<span class="line"><span>- Difficulté commune : ne pas savoir comment modifier pour que ce soit « assez bon »</span></span>
<span class="line"><span>- Alternative actuelle : demander aux anciens de relire, modifier soi-même en boucle</span></span>
<span class="line"><span>- JTBD possible :</span></span>
<span class="line"><span>  Quand je prépare ma candidature de stage, je veux juger plus vite si mon CV a atteint le niveau pour être envoyé,</span></span>
<span class="line"><span>  pour ne pas rester bloqué à « encore un peu de modification » et ne jamais l&#39;envoyer.</span></span></code></pre></div><p>Ce type de résultat est utile parce qu&#39;il vous aide à extraire des notes dispersées quelque chose qui ressemble davantage à un « besoin ».</p><h3 id="_12-3-laissez-l-ia-faire-une-recherche-en-ligne-legere" tabindex="-1">12.3 Laissez l&#39;IA faire une recherche en ligne légère <a class="header-anchor" href="#_12-3-laissez-l-ia-faire-une-recherche-en-ligne-legere" aria-label="Permalink to “12.3 Laissez l&#39;IA faire une recherche en ligne légère”">​</a></h3><p>Avant de vous lancer dans des entretiens à grande échelle, vous pouvez demander à l&#39;IA de faire un scan externe très léger, comme :</p><ul><li>Dans les forums ou communautés publics, comment les gens se plaignent-ils de ce problème</li><li>Les produits existants résolvent-ils principalement quelle couche du problème</li><li>Quelle est l&#39;alternative la plus courante des utilisateurs</li><li>Dans les avis fréquents, qu&#39;est-ce que les gens apprécient le plus et le moins</li></ul><p>Ce type de recherche ne remplace pas les entretiens avec de vrais utilisateurs, mais il est idéal comme échauffement en phase Discover, pour construire d&#39;abord une carte des problèmes.</p><p>Une entrée simple pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de rechercher :</span></span>
<span class="line"><span>« Quelles sont les douleurs les plus fréquentes quand les étudiants modifient leur CV et postulent pour des stages ? »</span></span>
<span class="line"><span>Priorisez les forums publics, les posts d&#39;expérience et les communautés de recherche d&#39;emploi.</span></span>
<span class="line"><span>Organisez en 5 problèmes les plus fréquents.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Douleurs fréquentes :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ne sait pas quoi mettre dans le CV, trop peu d&#39;expériences</span></span>
<span class="line"><span>2. Ne sait pas comment adapter pour différents postes</span></span>
<span class="line"><span>3. A modifié beaucoup de versions, mais n&#39;est toujours pas sûr que c&#39;est assez bon</span></span>
<span class="line"><span>4. Ne trouve personne de fiable pour relire</span></span>
<span class="line"><span>5. Le processus de candidature est complexe, tendance à procrastiner</span></span></code></pre></div><p>Ce type de résultat ne peut pas être considéré comme conclusion finale, mais il est idéal pour décider quel type de problème interviewer en priorité.</p><h3 id="_12-4-laissez-l-ia-jouer-le-role-de-«-contre-partie-»" tabindex="-1">12.4 Laissez l&#39;IA jouer le rôle de « contre-partie » <a class="header-anchor" href="#_12-4-laissez-l-ia-jouer-le-role-de-«-contre-partie-»" aria-label="Permalink to “12.4 Laissez l&#39;IA jouer le rôle de « contre-partie »”">​</a></h3><p>Très souvent, nous sommes trop attachés à nos propres idées. Vous pouvez demander à l&#39;IA de jouer un rôle de critique pour vous forcer à clarifier vos questions :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de jouer le rôle d&#39;un consultant en recherche produit très strict.</span></span>
<span class="line"><span>Voici mon hypothèse JTBD : [votre hypothèse]</span></span>
<span class="line"><span>Critiquez-la sous les angles suivants :</span></span>
<span class="line"><span>1. Le contexte est-il trop large</span></span>
<span class="line"><span>2. Le job est-il écrit comme une fonctionnalité plutôt qu&#39;une vraie progression</span></span>
<span class="line"><span>3. L&#39;alternative est-elle trop faible</span></span>
<span class="line"><span>4. Le critère de succès n&#39;est-il pas assez clair</span></span>
<span class="line"><span>5. Quel est le risque principal qui nécessite une validation pour cette hypothèse</span></span></code></pre></div><p>L&#39;avantage de cette approche est que vous découvrirez plus vite si vous regardez un besoin ou seulement une solution que vous aimez.</p><h2 id="📚-exercices" tabindex="-1">📚 Exercices <a class="header-anchor" href="#📚-exercices" aria-label="Permalink to “📚 Exercices”">​</a></h2><p>En vous basant sur le contenu ci-dessus, veuillez réaliser les exercices suivants :</p><ol><li>Choisissez une idée produit que vous avez récemment, et écrivez-la clairement avec une phrase JTBD</li><li>Complétez les 5 éléments pour cette idée : contexte, déclencheur, progression, alternative, critère de succès</li><li>Trouvez 3 utilisateurs potentiels, et demandez au moins une fois « quand est la dernière fois que vous avez rencontré ce problème »</li><li>Confiez les notes d&#39;entretien à l&#39;IA et organisez-les en 3 hypothèses JTBD prioritaires pour validation</li></ol><h2 id="lectures-complementaires" tabindex="-1">Lectures complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to “Lectures complémentaires”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute : Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online : What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom : Jobs-to-be-Done : A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural : Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{v as __pageData,b as default};
